import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"7、【師】 坎下坤上","description":"子夏易傳 - 7、【師】 坎下坤上","frontmatter":{"title":"7、【師】 坎下坤上","description":"子夏易傳 - 7、【師】 坎下坤上"},"headers":[],"relativePath":"classics/zixia/009.md","filePath":"classics/zixia/009.md"}'),i={name:"classics/zixia/009.md"};function r(_,p,c,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="_7、【師】-坎下坤上" tabindex="-1">7、【師】 坎下坤上 <a class="header-anchor" href="#_7、【師】-坎下坤上" aria-label="Permalink to “7、【師】 坎下坤上”">​</a></h1><p>卦辭：師，貞，丈人吉，無咎。</p><p>彖曰：師，眾也。貞，正也。能以眾正，可以王矣。剛中而應，行險而順，以此毒天下，而民從之，吉。又何咎矣。</p><p>子夏：五天位也，而以非陽居之，或有戰爭之事。二剛陽也，而能正眾，可崇任之，佐其尊而臣也。文人之謂，居中而奉，行險而順，以殺上。殺毒其人，而人從也。專其命，咎，則吉復大矣。又何咎焉。</p><p>象曰：地中有水，師。君子以容民畜眾。</p><p>子夏：地中有水，故能有得其潤，而保其廣地之用也。蓋象乎君子也。則能得其情而獲其治道，出於民也。故君子以容而畜之，顯仁以藏用也。</p><p>初六，師出以律，否臧兇。</p><p>象曰；師出以律，失律，兇也。</p><p>子夏：春秋傳言：執事順成，為臧逆，為否理。有必然之勝者，師出而謀合之。為臧，乃其律也。失之，是以兇也。夫律者，軍事之命也。師之興，主君不能親之，是以授其命而不授其事。名曰專徵。此古師之道也。軍誌曰：軍之所承於君者，師之可戰，君曰無戰，必戰可也。師不可戰，君曰戰之，無戰可也。故進不求其名，退不避其罪，本乎社稷之衛也。或以聽君主之制為律，豈足是哉。愼諸，其在授人以律乎。</p><p>九二，在師中，吉，無咎。王三錫命。</p><p>象曰：在師中，吉，承天寵也。王三錫命，懷萬邦也。</p><p>子夏：剛中而應，行險而順。受命而能正眾也。吉何咎哉。王者以天下為心，用兵非以怒也，平之非喜殺也。三錫命非私也，安萬邦而已矣。</p><p>六三，師或輿屍，兇。</p><p>象曰：師或輿屍，大無功也。</p><p>子夏：師之出也，任於一人。剛中者也。多則或矣。非其任也。何功之有，吉。二剛也。而以隂柔乘其上，是兼其領也。輿師之兇也。宜哉。無君上之命，則免矣。故曰或也。</p><p>六四，師左次，無咎。</p><p>象曰：左次，無咎。未失常也。</p><p>子夏：左者不用之地，待其師命而已，未失常也。</p><p>六五，田有禽，利執言，無咎。長子帥師，弟子輿屍，貞兇。</p><p>象曰：長子帥師，以中行也。弟子輿屍，使不當也。</p><p>子夏：居尊雖柔，待而有獲也。何以利乎，柔不能臨眾也。執命而授德人，則無咎矣。二剛中而繼體於五，其長子乎。命授一人，帥師可也。三柔弟子也。命不可二也。其輿屍也。</p><p>上六，大君有命，開國承家，小人勿用。</p><p>象曰：大君有命，以正功也。小人勿用，必亂邦也。</p><p>子夏：師之終復於大君者，居天下而無私。故誓師曰：用命賞於祖，不用命戮於社。功存社稷之公也，天下共之有。開國而封之者，承家而食之者，此功之分也。王執而正之，非惠之私也。小人不原於天命，不足於貴位，故至亂邦。此易之終戒也，而失於用也。</p>',24)])])}const f=a(i,[["render",r]]);export{m as __pageData,f as default};
